import json, subprocess, sys, time

ACTIONS=['ACTION4','ACTION1','ACTION2','ACTION3','ACTION5']
BASE=3
nodes=0
seen={}

def run(args):
    p=subprocess.run(['python','avo_tool.py',*args],text=True,capture_output=True)
    if p.returncode:
        if 'acknowledgement' in (p.stderr+p.stdout):
            subprocess.run(['python','avo_tool.py','acknowledge_supervisor','DFS will vary actions and backtrack deterministically from no-change branches.'],capture_output=True,text=True)
            return run(args)
        raise RuntimeError(p.stderr+p.stdout)
    return json.loads(p.stdout)

def obs_from_probe(d): return d['transition']['after']
def sig(o): return json.dumps(o['payload']['frame'][-1],separators=(',',':'))

def probe(a, why):
    global nodes
    nodes+=1
    return obs_from_probe(run(['probe',a,'--rationale',why]))

def dfs(o, depth, path):
    if o['progress']['levels_completed']>BASE:
        print('SOLVED',path); return path
    if depth==0:return None
    s=sig(o)
    if seen.get(s,-1)>=depth:return None
    seen[s]=depth
    for a in ACTIONS:
        before=sig(o)
        n=probe(a,f'Deterministic DFS branch at depth {len(path)}; vary controls and backtrack reversible states to find the level completion transition.')
        ns=sig(n)
        if n['progress']['levels_completed']>BASE:
            print('SOLVED',path+[a]);return path+[a]
        if ns!=before:
            z=dfs(n,depth-1,path+[a])
            if z:return z
            u=probe('ACTION7','Undo the explored deterministic branch to restore its parent observation.')
            # Animation variants can differ, but a second undo would over-backtrack.
            o=u
        if nodes>720:
            print('NODE_BUDGET');return None
    return None

# Prefix: start at c2 and walk to c5 immediately before the separated object.
o=run(['observe'])['observation']
path=[]
for _ in range(3):
    o=probe('ACTION4','Apply the known safe prefix to the cell immediately before the separated object.')
    path.append('ACTION4')
for lim in (6,8,10,12):
    print('limit',lim,'nodes',nodes,flush=True)
    z=dfs(o,lim,path)
    if z:
        open('solution.txt','w').write(' '.join(z));sys.exit(0)
print('UNSOLVED nodes',nodes)

